    def dump(self) -> str:
        """Emit this node as SysML text (loss-minimizing).

        Prefers the node's own ``raw_text`` verbatim, then recurses into
        children (also dump()-ing their raw_text and descendants) — so a
        full IR tree reconstructs the source in order.  A ``//`` line-comment
        raw_text must be newline-terminated or the canonical tokenizer would
        swallow every following token (the issue-#8 render_ir lesson).
        """
        out: list[str] = []
        if self.raw_text:
            out.append(_terminate_line_comment(self.raw_text))
        else:
            parts: list[str] = []
            parts.extend(self.modifiers)

            # W1-A: map the IR kind to its printable SysML keyword so
            # builder-built nodes dump valid text (`use case S`, not
            # `use_case S`).  Fall back to the stored kinds for anything the
            # map doesn't cover (raw parser kinds), matching prior behavior.
            def _print_kind() -> str:
                key = self.ir_kind or self.kind
                if not key:
                    return ""
                return _PRINT_KEYWORD.get(key, key)

            if self.short_name:
                # W1-4 r2 / r3 W1-6: reconstruct the short name as the angle
                # form "<s>" (parse_ir's short-name vocabulary), so build_node()
                # -> dump() does not drop it and does not emit non-SysML "~s".
                head0 = _print_kind()
                if self.name:
                    parts.append(f"{head0} <{self.short_name}> {self.name}")
                else:
                    parts.append(f"{head0} <{self.short_name}>")
            elif self.ir_kind or self.kind:
                head = _print_kind()
                if self.name:
                    parts.append(f"{head} {self.name}")
                elif "{" in head or head in ("brace_open", "brace_close"):
                    parts.append(head)
                # else: a bare kind with no name is not meaningful text
                # (e.g. the IR "root" node) — emit nothing rather than
                # malformed SysML.
            elif self.name:
                parts.append(self.name)
            if self.multiplicity:
                parts.append(self.multiplicity)
            if self.type_refs:
                # W1-4 r2: reconstruct the typed reference, matching the
                # builder's _render_sysml, so it isn't dropped on Node.dump.
                parts.extend(": " + t for t in self.type_refs)
            if self.value is not None:
                # Issue #26: value (and optional unit) — `attribute mass = 1000[kg];`
                if self.unit:
                    parts.append("= " + self.value + "[" + self.unit + "]")
                else:
                    parts.append("= " + self.value)
            if parts:
                out.append(" ".join(parts))
        for c in self.children:
            d = c.dump()
            if d:
                out.append(d)
        # r4 #8: parser-produced trees carry raw_text (already ;/{/} terminated)
        # and join as-is; builder-built nodes (no raw_text) enter the reconstruct
        # branch, so separate siblings with a newline or they concatenate.
        sep = "" if self.raw_text else "\n"
        return sep.join(out)

    def get_definition(self) -> dict:
        """Serialize back to an IR-JSON dict (preserving the IR coarse kind)."""
        d = {
            "kind": self.ir_kind or self.kind,
            "name": self.name,
            "short_name": self.short_name,
            "modifiers": list(self.modifiers),
            "type_refs": list(self.type_refs),
            "multiplicity": self.multiplicity,
            "source_span": list(self.source_span),
            "raw_text": self.raw_text,
            "fidelity": self.fidelity,
        }
        # Issue #26: only include value/unit when set, so get_definition stays
        # lossless vs an IR that never carried them (parser corpus path uses
        # raw_text for valued attrs).  A builder-built attribute carries both.
        if self.value is not None:
            d["value"] = self.value
            if self.unit is not None:
                d["unit"] = self.unit
        d["children"] = [c.get_definition() for c in self.children]
        return d


